# WAN-247: persisted user interaction records, never implicit Agent execution.
S['V3AgentToolCreate'] = obj({'name':string(minLength=1,maxLength=160),'kind':string(enum=['read','write']),'connector_id':string(minLength=1,maxLength=128)},['name','kind','connector_id'])
v3_route('post','/agent-tools','Register catalog metadata without any Agent grant',body=ref('V3AgentToolCreate'),response=obj({'id':string()},['id']),desc='Single environment; current human session, agents.manage and connectors.view required. Connector must belong to selected environment. Catalog storage has no Agent binding and cannot execute any tool; write tools remain human-approved proposals only. Registration and sanitized success audit are atomic.')
S['V3EvalDataset'] = obj({'id':string(),'name':string(),'source':string(enum=['incidents','runs','manual']),'count':integer(minimum=0)},['id','name','source','count'])
v3_route('get','/eval-datasets','Read persisted datasets and visible run counts',query=[v3_query('agent_id')],response=obj({'items':arr(ref('V3EvalDataset'))},['items']),desc='Current human session and environment agents.view. Optional Agent ID filters to datasets containing a currently visible run of that Agent. Count is deduplicated currently authorized run references; source is a provenance category and does not import incidents automatically. Bounded to 200 datasets and 2000 items per dataset; excess 413.')
v3_route('post','/eval-datasets','Create an empty persisted evaluation dataset',body=obj({'name':string(minLength=1,maxLength=160),'source':string(enum=['incidents','runs','manual'])},['name','source']),response=obj({'id':string()},['id']),desc='Current human session, single environment and environment agents.change. Starts with zero items; creation does not execute an evaluation or import external data.')
v3_route('post','/eval-datasets/{id}/items','Add a completed authorized run reference',body=obj({'run_id':string(minLength=1,maxLength=128)},['run_id']),response=obj({'count':integer(minimum=0)},['count']),desc='Dataset and run must share selected environment. Current environment agents.change and exact run application/current-owner-team agents.view required. Running run returns 409; duplicate references are idempotent and count includes only currently visible persisted runs. Item and sanitized audit commit atomically.')
v3_route('post','/agent-runs/{id}/annotations','Persist a human score and bounded note',body=obj({'score':integer(minimum=1,maximum=5),'note':string(maxLength=2000)},['score']),response=obj({'id':string(),'run_id':string(),'score':integer(minimum=1,maximum=5),'note':string(),'created_at':string(format='date-time')},['id','run_id','score','note','created_at']),desc='Single environment and current human exact run application/current-owner-team agents.change. Only completed runs; annotations are durable human observations, not computed evaluation scores. Audit contains score and IDs, never note content.')
v3_route('get','/prompts/{id}/versions','Read actual persisted Prompt version history',response=obj({'items':arr(obj({'version':string(),'created_at':string(format='date-time'),'author':string(),'current':v3_bool()},['version','created_at','author','current']))},['items']),desc='Current human session and exact Agent current active application/team/environment agents.view. Lists real persisted Prompt versions, author IDs and current pointer, never synthesized history. More than 1000 versions returns 413.')
for path in ['/agent-tools','/eval-datasets','/agent-runs/{id}/annotations']:
    P[path]['post']['responses']['201'] = P[path]['post']['responses']['200'].copy()
    P[path]['post']['responses']['201']['description'] = 'Persisted record'
S['V3MemoryPolicy'] = obj({'ttl_days':integer(enum=[30,90,180]),'proposers':string(enum=['human','human_ai']),'revision':integer(minimum=0),'automatic_expiry_available':v3_bool(),'ai_production_available':v3_bool(),'policy_effect':string(),'configured':v3_bool()},['ttl_days','proposers','revision','automatic_expiry_available','ai_production_available','policy_effect','configured'])
v3_route('patch','/memory/facts/{id}','Edit evidence-backed text with revision CAS',body=obj({'expected_revision':integer(minimum=1),'fact':string(minLength=1,maxLength=4000)},['expected_revision','fact']),response=ref('V3MemoryFactEvidence'),desc='Single environment and current human exact source scope knowledge.manage. Candidate or confirmed facts only. Current document/version/hash/attribution and old evidence must still match; new fact must be a verbatim excerpt of the same source. CAS mismatch or stale provenance returns 409; non-evidence text 422. State returns to candidate, old confirmation is cleared, provenance preserved and revision increments. No AI assertion is accepted. Success audit is atomic and excludes fact text.')
v3_route('get','/memory/policy','Read selected environment memory governance policy',response=ref('V3MemoryPolicy'),desc='Single selected environment, current human knowledge.view. Unconfigured default is ttl_days 90, proposers human and revision 0; TTL is enforced after a policy is explicitly persisted. human_ai expresses permitted proposal governance but no AI producer is connected.')
v3_route('put','/memory/policy','Persist memory policy with revision CAS',body=obj({'expected_revision':integer(minimum=0),'ttl_days':integer(enum=[30,90,180]),'proposers':string(enum=['human','human_ai'])},['expected_revision','ttl_days','proposers']),response=ref('V3MemoryPolicy'),desc='Single environment, current human environment knowledge.manage; persisted policy and audit are atomic. First write requires revision 0. TTL applies to memory view and confirmation from original confirmed_at, otherwise created_at, including historical facts; changing a policy never renews timestamps. Records remain in governance history and may be manually expired. human_ai does not start an AI producer.')
for key in ['agent','version','trigger']:
    P['/agent-runs']['get']['parameters'].append({'name':key,'in':'query','schema':arr(string()),'style':'form','explode':True})
P['/agent-runs']['get']['parameters'].append(v3_query('range',string(enum=['15m','30m','1h','6h','24h','7d','30d'])))
for key in ['connector','agent']:
    P['/agent-tools']['get']['parameters'].append({'name':key,'in':'query','schema':arr(string()),'style':'form','explode':True})
for key in ['source','confidence']:
    P['/memory']['get']['parameters'].append({'name':key,'in':'query','schema':arr(string()),'style':'form','explode':True})
P['/memory']['get']['description'] += ' Repeated source filters use exact visible document IDs; confidence supports high/medium/low/unknown, with only unknown matching because no confidence producer exists. Persisted TTL policies filter expired facts using confirmed_at otherwise created_at.'

# Catalog-only tool rows carry explicit empty Agent binding and connector identity.
tool_item = P['/agent-tools']['get']['responses']['200']['content']['application/json']['schema']['properties']['items']['items']
tool_item['properties'].update({'connector_id':string(),'catalog_only':v3_bool()})
P['/agent-tools']['get']['description'] += ' Also lists ungranted environment catalog records requiring environment agents.view and connectors.view; any Agent facet excludes these ungranted rows. Repeated connector and agent facets use exact IDs before bounded reads.'
P['/agent-runs']['get']['description'] += ' Repeated agent/version/trigger facets and range restrict the authorized persisted scope before bounded aggregates and pagination; range also sets trend bucket interval/window. Absent range preserves prior all-history list and 24-hour trend.'
